changed as (
 update public.businesses b set status='pending_review',verified=false
 from candidates c where b.id=c.id and b.name=c.name and b.city=c.city and b.phone is not distinct from c.phone and b.address is not distinct from c.address
 and b.status='approved' and b.verified=true
 returning b.id,c.reason,c.source
)
